import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { authorizeSettings } from '@/lib/api-auth';

// Defaults reproduce ModernNavbar's current, unconditional appearance exactly
// (mode: 'solid') so no existing site changes appearance until a Builder_Admin
// explicitly opts into 'floating'. Mirrors src/hooks/useSiteSettings.ts's defaults.
const DEFAULT_HEADER_SETTINGS = {
  mode: 'solid' as const,
  transitionDurationMs: 250,
  floatingState: {
    background: 'transparent',
    backgroundOpacity: 0,
    backdropBlur: false,
    textColor: '#ffffff',
    linkHoverColor: '#ffffff',
    logoVariant: 'light' as const,
    logoUrlOverride: '',
    showBorder: false,
    showShadow: false
  },
  solidState: {
    background: '',
    backgroundOpacity: 0.9,
    backdropBlur: true,
    textColor: '',
    linkHoverColor: '',
    logoVariant: 'dark' as const,
    logoUrlOverride: '',
    showBorder: false,
    showShadow: false
  },
  autoHide: { enabled: false },
  height: { desktop: 64, mobile: 56 }
};

// GET is intentionally left unauthenticated: src/hooks/useSiteSettings.ts fetches
// this route from the public site's root layout (logo, theme, header, contact-sales
// visibility) for every anonymous visitor, so it cannot require a Bearer token.
export async function GET(request: NextRequest) {
  try {
    const settings = await prisma.siteSettings.findFirst();
    
    if (!settings) {
      // Return default settings if none exist
      const defaultSettings = {
        logo: {
          url: '',
          alt: 'English Website',
          width: 120,
          height: 40
        },
        languages: {
          showInHeader: true,
          defaultLanguage: 'en',
          enabledLanguages: ['en', 'ar']
        },
        contactSales: {
          show: true,
          text: 'Contact Sales',
          url: '/contact-sales'
        },
        theme: {
          defaultTheme: 'light',
          autoSwitchByTime: false,
          darkModeStart: '18:00',
          darkModeEnd: '06:00'
        },
        favicon: {
          url: '/favicon.ico',
          appleTouchIcon: '/apple-touch-icon.png',
          manifest: '/site.webmanifest'
        },
        header: DEFAULT_HEADER_SETTINGS
      };

      const response = NextResponse.json(defaultSettings);
      response.cookies.set('defaultLanguage', defaultSettings.languages.defaultLanguage, {
        path: '/',
        maxAge: 60 * 60 * 24 * 365 // 1 year
      });
      return response;
    }

    const saved = JSON.parse(settings.data);

    const merged = {
      ...saved,
      footer: {
        companyName: 'English Website',
        tagline: '',
        description: '',
        columns: [],
        bottomBar: { show: true, copyrightText: '© {year} English Website. All rights reserved.', showSocialLinks: true, socialLinks: [] },
        style: { backgroundColor: '', textColor: '', linkColor: '', borderColor: '', padding: 'py-12' },
        ...saved.footer,
        contactInfo: {
          show: true,
          email: '',
          phone: '',
          address: '',
          ...(saved.footer?.contactInfo || {})
        }
      },
      header: {
        ...DEFAULT_HEADER_SETTINGS,
        ...saved.header,
        floatingState: { ...DEFAULT_HEADER_SETTINGS.floatingState, ...(saved.header?.floatingState || {}) },
        solidState: { ...DEFAULT_HEADER_SETTINGS.solidState, ...(saved.header?.solidState || {}) },
        autoHide: { ...DEFAULT_HEADER_SETTINGS.autoHide, ...(saved.header?.autoHide || {}) },
        height: { ...DEFAULT_HEADER_SETTINGS.height, ...(saved.header?.height || {}) }
      }
    };

    const response = NextResponse.json(merged);
    response.cookies.set('defaultLanguage', merged.languages?.defaultLanguage || 'en', {
      path: '/',
      maxAge: 60 * 60 * 24 * 365 // 1 year
    });
    return response;
  } catch (error) {
    console.error('Failed to fetch settings:', error);
    return NextResponse.json(
      { error: 'Failed to fetch settings' },
      { status: 500 }
    );
  }
}

export async function POST(request: NextRequest) {
  try {
    const auth = authorizeSettings(request);
    if (!auth.ok) return auth.response;

    const settingsData = await request.json();

    // Validate required fields
    if (!settingsData.logo || !settingsData.languages || !settingsData.contactSales || !settingsData.theme) {
      return NextResponse.json(
        { error: 'Missing required settings data' },
        { status: 400 }
      );
    }

    // Check if settings already exist
    const existingSettings = await prisma.siteSettings.findFirst();

    if (existingSettings) {
      // Update existing settings
      await prisma.siteSettings.update({
        where: { id: existingSettings.id },
        data: {
          data: JSON.stringify(settingsData),
          updatedAt: new Date()
        }
      });
    } else {
      // Create new settings
      await prisma.siteSettings.create({
        data: {
          data: JSON.stringify(settingsData)
        }
      });
    }

    const response = NextResponse.json({ success: true });
    response.cookies.set('defaultLanguage', settingsData.languages.defaultLanguage, {
      path: '/',
      maxAge: 60 * 60 * 24 * 365 // 1 year
    });
    return response;
  } catch (error) {
    console.error('Failed to save settings:', error);
    return NextResponse.json(
      { error: 'Failed to save settings' },
      { status: 500 }
    );
  }
}